import ezdxf, sys
doc = ezdxf.readfile(sys.argv[1])
msp = doc.modelspace()
for e in msp:
    d = e.dxftype()
    s = f"{d} h={e.dxf.handle} layer={e.dxf.layer}"
    if d == 'CIRCLE':
        s += f" c={tuple(e.dxf.center)} r={e.dxf.radius}"
    elif d == 'LINE':
        s += f" {tuple(e.dxf.start)}->{tuple(e.dxf.end)}"
    elif d == 'TEXT':
        s += f" {tuple(e.dxf.insert)} {e.dxf.text!r}"
    elif d == 'MTEXT':
        s += f" {tuple(e.dxf.insert)} {e.text!r}"
    elif d == 'DIMENSION':
        s += f" type={e.dimtype} text={e.dxf.text!r} block={e.dxf.geometry} style={e.dxf.dimstyle}"
        for k in ('defpoint', 'defpoint2', 'defpoint3', 'defpoint4', 'text_midpoint'):
            if e.dxf.hasattr(k):
                s += f" {k}={tuple(e.dxf.get(k))}"
        s += f" meas={e.dxf.get('actual_measurement')}"
        ov = e.get_dim_style().dxf.name
    elif d == 'LWPOLYLINE':
        s += f" {list(e.get_points('xy'))} closed={e.closed}"
    elif d == 'INSERT':
        s += f" {e.dxf.name} {tuple(e.dxf.insert)}"
    print(s)
print(doc.header.get('$INSUNITS'), doc.dxfversion)

