import ezdxf, sys
doc = ezdxf.readfile(sys.argv[1])
msp = doc.modelspace()
dim = msp.query('DIMENSION[handle=="D2"]')[0] if False else doc.entitydb['D2']
print('overrides:', dim.get_acad_dstyle(dim.get_dim_style()) if hasattr(dim, 'get_acad_dstyle') else None)
print('xdata:', dim.xdata.data if dim.xdata else None)
for e in doc.blocks.get(dim.dxf.geometry):
    d = e.dxftype()
    s = f"  {d} layer={e.dxf.layer}"
    if d == 'LINE':
        s += f" {tuple(e.dxf.start)}->{tuple(e.dxf.end)}"
    elif d == 'MTEXT':
        s += f" {tuple(e.dxf.insert)} {e.text!r} h={e.dxf.char_height}"
    elif d in ('SOLID', 'INSERT'):
        s += f" {e.dxf.get('name')} {tuple(e.dxf.get('insert', (0, 0, 0)))}"
    print(s)
print('block names:', [b.name for b in doc.blocks])
tb = doc.blocks.get('TB')
for e in tb:
    print('TB', e.dxftype(), getattr(e.dxf, 'text', ''), e.dxf.get('tag', ''))
ins = doc.entitydb['ED']
for a in ins.attribs:
    print('ATTR', a.dxf.tag, a.dxf.text)
for e in doc.entitydb.values():
    if e.dxftype() in ('TEXT', 'MTEXT', 'ATTRIB', 'ATTDEF'):
        t = e.dxf.text if e.dxftype() != 'MTEXT' else e.text
        if '10' in t or 'Ø' in t or '%%c' in t.lower():
            print('HIT', e.dxftype(), e.dxf.handle, repr(t))
print('LOGO hatch', doc.entitydb['E2'].paths)

