import ezdxf
a = ezdxf.readfile('part_before_r2.dxf')
b = ezdxf.readfile('part.dxf')
print('F3', a.entitydb['F3'].dxf.all_existing_dxf_attribs(), b.entitydb['F3'].dxf.all_existing_dxf_attribs())
for k in a.header.varnames():
    if a.header.get(k) != b.header.get(k):
        print(k, a.header.get(k), '->', b.header.get(k))
for h in ('E1', 'E2', 'E3', 'E0', 'ED'):
    print(h, b.entitydb[h].dxftype(), 'present')
print([(x.dxf.tag, x.dxf.text) for x in b.entitydb['ED'].attribs])

